                Item("A-124", R.drawable.b_a124, "Born To Serve A Purpose, A124 Was Programmed To Be A Killing Machine. She Was Certainly Not Built For Human Interactions And Complicated Emotions, But Who Could Stop A Young Mind From Trying? With Those Battle Skills And A Curious Mind, The World Is Literally Her Oyster.", listOf(R.string.stat_age to "18 Years", R.string.stat_birthday to "1st January", R.string.stat_occupation to "AI Battle Robot", R.string.stat_hobby to "People watching"), thumb = R.drawable.a124),
                Item("A-Patroa", R.drawable.b_apatroa, "A-Patroa Is A Strong, Confident Woman Who Runs A Music Shop In The Middle Of A Dangerous Neighborhood. Her Shop Doubles As A Safe Haven; Anyone Can Come To Her For Help. On Top Of That, She Uses Her Music To Help People Experience Their Lives In New And Different Ways.", listOf(R.string.stat_age to "28 Years", R.string.stat_birthday to "30th March", R.string.stat_occupation to "Music Shop Owner", R.string.stat_hobby to "Playing The Bass"), thumb = R.drawable.apatroa),
