                Item("Alvaro", R.drawable.b_alvaro, "Alvaro Is A Young Man With An Explosive Personality. A Childhood Accident Gifted Him With Special Explosive Powers, At The Cost Of His Memories. The Only Constant He Has Found In His Life Is Kapella, His Childhood Best Friend, Whom He No Longer Consciously Remembers.", listOf(R.string.stat_age to "26 Years", R.string.stat_birthday to "28th May", R.string.stat_occupation to "Explosive Capabilities", R.string.stat_hobby to "BBQ"), thumb = R.drawable.alvaro),
