                Item("Clu", R.drawable.b_clu, "Clu Grew Up In A Suburb Of A Large City. When She Was A Teenager, Her Dad Was Recruited For The War Effort And Never Came Home. Clu Became A Private Eye Detective After Graduating High School In Hopes She Could Uncover Details On Her Dad's Disappearance.", listOf(R.string.stat_age to "24 Years", R.string.stat_birthday to "28th February", R.string.stat_occupation to "Private Eye", R.string.stat_hobby to "Escape Rooms"), thumb = R.drawable.clu),
                Item("D-Bee", R.drawable.b_dbee, "D-Bee Has An Extroverted Personality And Enjoys Meeting New People. He Believes That The Meaning Of Life Is Creating, And That's Why He Became A Creator. He's Also Fascinated By Dancing And Music.", listOf(R.string.stat_age to "19 Years", R.string.stat_birthday to "23th September", R.string.stat_occupation to "Street Dancer", R.string.stat_hobby to "Music Concerts"), thumb = R.drawable.dbee),
                Item("Dasha", R.drawable.b_dasha, "Dasha Was A Very Happy And Productive Child, But Then A Series Of Unfortunate Events Came Into Her Life. When She Was 18 She Had To Make A Choice: Fight For Survival, Let Her Past Destroy Her, Or Let It All Go And Have Fun. She Chose The Third Option.", listOf(R.string.stat_age to "25 Years", R.string.stat_birthday to "8th December", R.string.stat_occupation to "Partier", R.string.stat_hobby to "Pranks"), thumb = R.drawable.dasha),
