                Item("Jota", R.drawable.b_jota, "Jota Grew Up In A Middle-Class Family, Was An Average Student, And Had A Family Who Loved Him. Overall A Pretty Normal Life - But He Felt Trapped And Needed More Action. He Lived In A City Of Skyscrapers And Started Climbing To Find Places To See The Sky.", listOf(R.string.stat_age to "31 Years", R.string.stat_birthday to "23th June", R.string.stat_occupation to "Student", R.string.stat_hobby to "Find Places To See The Sky"), thumb = R.drawable.jota),
                Item("K", R.drawable.b_k, "K Was A Smart Kid, But Like Most Kids His Age He Didn't Take School Seriously. At 16 He Got Into A Car Crash And Injured His Spine. Doctors Told Him He Would Never Walk Again. But He Refused To Give Up - In A Year He Was Walking; In Two He Was Playing Sports.", listOf(R.string.stat_age to "31 Years", R.string.stat_birthday to "10th June", R.string.stat_occupation to "Expertise To The Fight", R.string.stat_hobby to "Playing Sports"), thumb = R.drawable.kk),
