                Item("Luna", R.drawable.b_luna, "Luna Is The Daughter Of A Complicated Man With A Complicated Past. When Her Father's Leadership In The Guild Was Challenged And He Was Eventually Kidnapped, Luna Had To Step Up, Take Charge Of The Group, And Restore Order To The Community.", listOf(R.string.stat_age to "28 Years", R.string.stat_birthday to "18th March", R.string.stat_occupation to "Guild Leader", R.string.stat_hobby to "Dealing Damage"), thumb = R.drawable.luna),
