                Item("Maxim", R.drawable.b_maxim, "Maxim Felt Guilty That His Sister, Misha, Left School To Take Care Of Him. He Turned To Food-Eating V-Tubing As His Part-Time Job. One Day, He And His Schoolmate Kelly Were Abducted And Sent To The Island Of Bermuda, Which Would Change Him For The Better.", listOf(R.string.stat_age to "17 Years", R.string.stat_birthday to "30th November", R.string.stat_occupation to "Food-Eating V-Tuber", R.string.stat_hobby to "Food-Eating"), thumb = R.drawable.maxim),
