                Item("Misha", R.drawable.b_misha, "After Her Parents Were Killed, Misha Became A Racecar Driver To Pay The Bills And Support Herself And Her Brother, Maxim. One Day, Maxim Went Missing And She Dropped Everything To Find Him, Crossing Paths With Andrew Along The Way.", listOf(R.string.stat_age to "19 Years", R.string.stat_birthday to "26th February", R.string.stat_occupation to "Racecar Driver", R.string.stat_hobby to "Operate Vehicles"), thumb = R.drawable.misha2),
