                Item("Otho", R.drawable.b_otho, "Otho Has An Imaginative Yet Very Practical Mind. He Is Scared To Death Of Forgetting The Memories Of His Past And Is Trying To Find Ways To Preserve It. He Has Developed A Device That Allows Him To See Others' Intentions.", listOf(R.string.stat_age to "21 Years", R.string.stat_birthday to "31st November", R.string.stat_occupation to "Developed A Device", R.string.stat_hobby to "Memory Master"), thumb = R.drawable.otho),
                Item("Paloma", R.drawable.b_paloma, "Paloma Has A Painful Past That She Does Not Talk About Often. A Beauty Queen Raised In The Poorest Suburbs Of Her Country, She Used To Be Every Girl's Role Model. But Now She Is The Epitome Of Evil, An Arms Dealer Who Controls The Underworld.", listOf(R.string.stat_age to "20 Years", R.string.stat_birthday to "4th August", R.string.stat_occupation to "Epitome Of Evil", R.string.stat_hobby to "Assault Rifles"), thumb = R.drawable.paloma),
                Item("Santino", R.drawable.b_santino, "Born In Poverty, Santino Loved Art Ever Since He Was A Child. He Studied At A Renowned Art School Where His Talent In Design Flourished. After Graduating, Santino Established His Fashion Brand, Angelic, And Became A Celebrity With A Keen Eye For Marketing.", listOf(R.string.stat_age to "34 Years", R.string.stat_birthday to "15th October", R.string.stat_occupation to "Trickster Of The Game", R.string.stat_hobby to "Generate A Decoy"), thumb = R.drawable.santino),
