                Item("Wukong", R.drawable.b_wukong, "Wukong Is A Humorous Character. Despite His Mythical Nature, Wukong Has A Bit Of A Silly Ability And Story In-Game. Still, Wukong Is A Strong Character, As His Ability Can Provide Tons Of Stealth. A Monkey That Looks Like A Human Being - He Still Likes Bananas, Though.", listOf(R.string.stat_age to "08 Years", R.string.stat_birthday to "13th December", R.string.stat_occupation to "Provide Tons Of Stealth", R.string.stat_hobby to "Mythical Nature"), thumb = R.drawable.wukong),
